mapper.select:
select id, account, employee_no, name, dept_code, dept_name, dept_path, position_name, status
from sys_user
where status = 1

    and (
        dept_path = #{deptPath}
        or (
            left(dept_path, char_length(#{deptPath})) = #{deptPath}
            and substring(dept_path, char_length(#{deptPath}) + 1, 1) = '_'
        )
    )


    and (
        name like concat('%', #{keyword}, '%')
        or account like concat('%', #{keyword}, '%')
        or employee_no like concat('%', #{keyword}, '%')
    )

order by name, account
